INSERT INTO public.treatment_recommendations
(target_condition, treatment_type, title, product_name, active_ingredient, dosage_rate, application_guidance, waiting_period_days, citation_source, citation_url)
VALUES
    ('Anthracnose', 'Biological', 'Pseudomonas fluorescens spray on flowers and fruit bunches', 'Pseudomonas fluorescens (strain FP 7) formulation', 'Pseudomonas fluorescens', '5 g per litre of water', 'Spray flowers and bunches at 3-week intervals from October; 5 to 7 sprays in total.', NULL, 'TNAU Agritech Portal, Crop Protection: Mango, Anthracnose', 'https://agritech.tnau.ac.in/crop_protection/mango_1.html'),
    ('Anthracnose', 'Chemical', 'Copper oxychloride spray for leaf infection', 'Copper oxychloride', 'Copper oxychloride', '0.3% spray', 'Collect and burn diseased leaves, twigs and fruits first. Then spray the foliage.', NULL, 'National Horticulture Mission, IPM Schedule for Mango Pests, Extension Bulletin No. 1 (2012), hosted on the TNAU Agritech Portal', 'https://agritech.tnau.ac.in/horticulture/pdf/tech_bulletin/national/IPM-Mango-Revised-Sept2011.pdf'),
    ('Anthracnose', 'Chemical', 'Carbendazim spray for blossom infection', 'Carbendazim (e.g. Bavistin)', 'Carbendazim', '0.1% spray', 'Spray at 15-day intervals during flowering. For pre-harvest sprays, the last spray must fall 15 days before harvest.', 15, 'National Horticulture Mission, IPM Schedule for Mango Pests, Extension Bulletin No. 1 (2012), hosted on the TNAU Agritech Portal', 'https://agritech.tnau.ac.in/horticulture/pdf/tech_bulletin/national/IPM-Mango-Revised-Sept2011.pdf'),
    ('Bacterial Canker', 'Cultural', 'Sanitation and windbreaks', 'N/A', 'N/A', 'N/A', 'Inspect the orchard regularly, remove infected parts, plant windbreaks to reduce wounding of leaves, and raise rootstock seedlings only from stones of healthy fruits.', NULL, 'National Horticulture Mission, IPM Schedule for Mango Pests, Extension Bulletin No. 1 (2012), hosted on the TNAU Agritech Portal', 'https://agritech.tnau.ac.in/horticulture/pdf/tech_bulletin/national/IPM-Mango-Revised-Sept2011.pdf'),
    ('Bacterial Canker', 'Chemical', 'Copper oxychloride spray in severe infection', 'Copper oxychloride', 'Copper oxychloride', '0.3% spray', 'For severe infection. (The source also lists Streptocycline; it is not suggested here because a phase-out of streptomycin and tetracycline in agriculture has been ordered in draft. Check its current status with your agriculture officer.)', NULL, 'National Horticulture Mission, IPM Schedule for Mango Pests, Extension Bulletin No. 1 (2012), hosted on the TNAU Agritech Portal', 'https://agritech.tnau.ac.in/horticulture/pdf/tech_bulletin/national/IPM-Mango-Revised-Sept2011.pdf'),
    ('Powdery Mildew', 'Chemical', 'Wettable sulphur spray at early panicle stage', 'Wettable sulphur', 'Sulphur', '0.2% spray (2 g per litre of water)', 'Spray when panicles are 3 to 4 inches long; a second application about 15 days later. Avoid spraying at full bloom.', NULL, 'TNAU Agritech Portal, Crop Protection: Mango, Powdery mildew; National Horticulture Mission IPM Schedule for Mango Pests (2012)', 'https://agritech.tnau.ac.in/crop_protection/mango_2.html'),
    ('Sooty Mold', 'Cultural', 'Control the honeydew insects, then spray starch', 'Starch or maida (flour) solution', 'Starch', 'Boil 1 kg starch or maida in 5 litres of water, then dilute to 20 litres', 'First control the insects whose honeydew feeds the mould (hoppers, scales, mealybugs). Then spray the starch; it dries into flakes that fall off with the mould. (The NHM bulletin gives a 2% starch spray.)', NULL, 'TNAU Agritech Portal, Crop Protection: Mango, Sooty mould', 'https://agritech.tnau.ac.in/crop_protection/mango_7.html'),
    ('Fruit Fly', 'Cultural', 'Destroy fallen fruit and plough in summer', 'N/A', 'N/A', 'N/A', 'Collect fallen infested fruits and bury them in a pit. Plough in summer to expose the pupae.', NULL, 'TNAU Agritech Portal, Crop Protection: Mango, Fruit fly', 'https://agritech.tnau.ac.in/crop_protection/mango/mango_8.html'),
    ('Fruit Fly', 'Biological', 'Methyl eugenol lure traps', 'Methyl eugenol trap', 'Methyl eugenol (lure)', '10 traps per hectare', 'Hang traps during the fruiting period (April to August in the source), tied 3 to 5 feet above the ground. The source''s trap mixture uses malathion, which is banned for use on mango in India (S.O. 4294(E), 3 Oct 2023): use only a trap insecticide whose label allows this use.', NULL, 'National Horticulture Mission, IPM Schedule for Mango Pests, Extension Bulletin No. 1 (2012), hosted on the TNAU Agritech Portal', 'https://agritech.tnau.ac.in/horticulture/pdf/tech_bulletin/national/IPM-Mango-Revised-Sept2011.pdf'),
    ('Mealy Bug', 'Cultural', 'Polythene trunk banding', 'Polythene sheet, 400 gauge, 20 cm wide, with fruit-tree grease', 'N/A (physical barrier)', 'One band per tree, 50 cm above the ground', 'Band the trunk in the middle of December, below the junction of the branches. Tie with jute thread and smear grease on the lower edge of the band so the nymphs cannot climb.', NULL, 'TNAU Agritech Portal, Crop Protection: Mango, Giant mealybug', 'https://agritech.tnau.ac.in/crop_protection/mango/mango_15.html'),
    ('Mealy Bug', 'Biological', 'Release of the Australian ladybird beetle', 'Cryptolaemus montrouzieri', 'Cryptolaemus montrouzieri (predator)', '10 beetles per tree', 'Release on infested trees.', NULL, 'TNAU Agritech Portal, Crop Protection: Mango, Giant mealybug', 'https://agritech.tnau.ac.in/crop_protection/mango/mango_15.html'),
    ('Scale Insect', 'Cultural', 'Prune infested parts and remove attendant ants', 'N/A', 'N/A', 'N/A', 'Prune heavily infested branches to open the canopy and destroy them immediately. Removing the ants that tend the scales lets natural enemies control them. (The chemicals named in the sources, phosphamidon and dimethoate, are banned or restricted for mango in India and are not suggested.)', NULL, 'National Horticulture Mission, IPM Schedule for Mango Pests (2012), hosted on the TNAU Agritech Portal; TNAU Agritech Portal, Crop Protection: Mango, Scales', 'https://agritech.tnau.ac.in/horticulture/pdf/tech_bulletin/national/IPM-Mango-Revised-Sept2011.pdf'),
    ('Mango Hopper', 'Biological', 'Neem (azadirachtin) spray at the start of hopper build-up', 'Azadirachtin 3000 ppm', 'Azadirachtin', '2 mL per litre of water', 'Spray at the initial stage of the hopper population. Keep the canopy open by pruning overcrowded branches after the rainy season.', NULL, 'National Horticulture Mission, IPM Schedule for Mango Pests, Extension Bulletin No. 1 (2012), hosted on the TNAU Agritech Portal', 'https://agritech.tnau.ac.in/horticulture/pdf/tech_bulletin/national/IPM-Mango-Revised-Sept2011.pdf'),
    ('Mango Hopper', 'Chemical', 'Imidacloprid spray at panicle stages (need-based)', 'Imidacloprid 200 SL', 'Imidacloprid', '0.25 mL per litre of water', 'Only if there are more than 5-10 hoppers per panicle: first spray early in panicle formation, second at full panicle length, third after fruit set (pea size). Minimise chemical sprays and rotate insecticides.', NULL, 'National Horticulture Mission, IPM Schedule for Mango Pests, Extension Bulletin No. 1 (2012), hosted on the TNAU Agritech Portal', 'https://agritech.tnau.ac.in/horticulture/pdf/tech_bulletin/national/IPM-Mango-Revised-Sept2011.pdf'),
    ('Stem Borer', 'Cultural', 'Remove infested branches and plug the bore holes', 'Kerosene- or petrol-soaked cotton, mud plug', 'N/A', 'One soaked cotton plug per hole', 'Cut and destroy affected branches with grubs and pupae. Clean each hole, insert cotton wool soaked in kerosene or petrol and plug it with mud. (The source also lists dichlorvos, which is banned in India and is not suggested.)', NULL, 'National Horticulture Mission, IPM Schedule for Mango Pests, Extension Bulletin No. 1 (2012), hosted on the TNAU Agritech Portal', 'https://agritech.tnau.ac.in/horticulture/pdf/tech_bulletin/national/IPM-Mango-Revised-Sept2011.pdf'),
    ('Stem Borer', 'Biological', 'Entomopathogenic fungi', 'Metarhizium anisopliae or Beauveria bassiana formulation', 'Metarhizium anisopliae / Beauveria bassiana', 'As per product label', 'Use as directed on the product label.', NULL, 'National Horticulture Mission, IPM Schedule for Mango Pests, Extension Bulletin No. 1 (2012), hosted on the TNAU Agritech Portal', 'https://agritech.tnau.ac.in/horticulture/pdf/tech_bulletin/national/IPM-Mango-Revised-Sept2011.pdf');
